import {openNews} from './profile-links.mjs';
export async function memberProfile({member,state,act,element,button,busy,avatar,signedImage}){
 const d=element('dialog',undefined,'member-profile'),head=element('header',undefined,'member-profile-bar'),content=element('div');head.append(element('h2','الملف الشخصي'),button('✕',()=>{d.close();d.remove()},'text-button'));d.append(head,content);document.body.append(d);d.showModal();let generation=0,scope='mentions',offset=0,profile,grid,more,count;const call=(action,data={})=>act('member_social',action,{member,...data});
 async function load(){const data=await call('profile');if(!d.isConnected||!d.open)return;profile=data;content.replaceChildren();const summary=element('section',undefined,'member-summary'),pic=element('span',data.display_name?.slice(0,1),'avatar member-avatar'),info=element('div');summary.append(pic,info);await avatar(data.avatar_path,pic);const stats=element('div',undefined,'member-stats');for(const[key,label]of [['posts','منشورات'],['followers','متابعون'],['following_count','يتابع']]){const cell=element('div');cell.append(element('strong',String(data[key]||0)),element('small',label));stats.append(cell)}info.append(stats);content.append(summary,element('h3',data.display_name,'member-display-name'));if(data.bio)content.append(element('p',data.bio,'member-bio'));if(member!==state.user.id){const follow=button(data.following?'تتابعه ✓':'متابعة',()=>busy(follow,async()=>{profile=await call(profile.following?'unfollow':'follow');follow.textContent=profile.following?'تتابعه ✓':'متابعة';follow.classList.toggle('secondary',profile.following);follow.classList.toggle('primary',!profile.following);stats.children[1].querySelector('strong').textContent=profile.followers}),'follow-button '+(data.following?'secondary':'primary'));follow.disabled=!!state.readOnly;content.append(follow,element('p','تصلك تنبيهات عند نشره خبرًا أو ذكره في خبر.','muted follow-hint'))}else content.append(element('p','بروفايلك كما يظهر لأعضاء العائلة.','muted'));
 const tabs=element('nav',undefined,'member-grid-tabs');tabs.setAttribute('aria-label','منشورات الحساب');for(const[key,label]of [['posts','▦ منشوراته'],['mentions','＠ أخبار ذُكر فيها']]){const b=button(label,async()=>{scope=key;for(const t of tabs.children)t.setAttribute('aria-pressed',String(t===b));await loadGrid(true)},'text-button');b.setAttribute('aria-pressed',String(scope===key));tabs.append(b)}grid=element('div',undefined,'member-photo-grid');count=element('p',undefined,'muted');count.setAttribute('role','status');more=button('عرض المزيد',()=>busy(more,()=>loadGrid(false)),'secondary');content.append(tabs,grid,count,more);await loadGrid(true)}
 async function loadGrid(reset){const n=++generation;if(reset){offset=0;grid.replaceChildren();count.textContent='جاري تحميل الصور…'}more.disabled=true;try{const rows=await call('grid',{scope,offset});if(n!==generation||!d.open||!d.isConnected)return;offset+=rows.length;for(const p of rows){const tile=button('',()=>{d.close();d.remove();openNews(p.id)},'member-photo-tile');tile.setAttribute('aria-label','فتح الخبر: '+p.title);const paths=p.image_paths?.length?p.image_paths:p.image_path?[p.image_path]:[];if(paths.length){const image=element('img');image.alt=p.title;image.loading='lazy';tile.append(image);signedImage(paths[0]).then(url=>{if(tile.isConnected)image.src=url}).catch(()=>{image.remove();tile.append(element('span','▧','photo-unavailable'))});if(paths.length>1)tile.append(element('span','▣','album-indicator'))}else{tile.classList.add('text-only-tile');tile.append(element('span','▤'));tile.setAttribute('title',p.title)}grid.append(tile)}count.textContent=offset?'':'لا توجد أخبار منشورة في هذا التبويب.';more.hidden=rows.length<30}finally{if(n===generation)more.disabled=false}}
 d.addEventListener('close',()=>{generation++;content.replaceChildren()});try{await load()}catch(e){content.replaceChildren(element('p',e.message))}return d;
}
